let file = """{"version":3,"file":"commandStore-Bx6jasRH.js","names":[],"sources":["../../src/composables/useErrorHandling.ts","../../src/lib/litegraph/src/canvas/CanvasInteractionMode.ts","../../src/platform/keybindings/reserved.ts","../../src/platform/keybindings/keyCombo.ts","../../src/platform/keybindings/keybinding.ts","../../src/platform/keybindings/keybindingStore.ts","../../src/stores/commandStore.ts"],"sourcesContent":["import { t } from '@/i18n'\nimport { useToast } from '@/components/ui/toast/toastStore'\n\n/**\n * Strategy for recovering from specific error conditions.\n * Allows operations to be retried after resolving the error condition.\n *\n * @template TArgs - The argument types of the operation to be retried\n * @template TReturn - The return type of the operation\n *\n * @example\n * ```typescript\n * const networkRecovery: ErrorRecoveryStrategy = {\n *   shouldHandle: (error) => error instanceof NetworkError,\n *   recover: async (error, retry) => {\n *     await waitForNetwork()\n *     await retry()\n *   }\n * }\n * ```\n */\nexport interface ErrorRecoveryStrategy<\n  TArgs extends unknown[] = unknown[],\n  TReturn = unknown\n> {\n  /**\n   * Determines if this strategy should handle the given error.\n   * @param error - The error to check\n   * @returns true if this strategy can handle the error\n   */\n  shouldHandle: (error: unknown) => boolean\n\n  /**\n   * Attempts to recover from the error and retry the operation.\n   * This function is responsible for:\n   * 1. Resolving the error condition (e.g., reauthentication, network reconnect)\n   * 2. Calling retry() to re-execute the original operation\n   * 3. Handling the retry result (success or failure)\n   *\n   * @param error - The error that occurred\n   * @param retry - Function to retry the original operation\n   * @param args - Original arguments passed to the operation\n   * @returns Promise that resolves when recovery completes (whether successful or not)\n   */\n  recover: (\n    error: unknown,\n    retry: (...args: TArgs) => Promise<TReturn> | TReturn,\n    args: TArgs\n  ) => Promise<void>\n}\n\nexport function useErrorHandling() {\n  const toast = useToast()\n  const toastErrorHandler = (error: unknown) => {\n    const isNetworkError =\n      error instanceof TypeError &&\n      /failed to fetch|networkerror|load failed/i.test(error.message)\n    const message = isNetworkError\n      ? t('g.disconnectedFromBackend')\n      : error instanceof Error\n        ? error.message\n        : t('g.unknownError')\n    toast.error(t('g.error'), { description: message })\n    console.error(error)\n  }\n\n  const wrapWithErrorHandling =\n    <TArgs extends unknown[], TReturn>(\n      action: (...args: TArgs) => TReturn,\n      errorHandler?: (error: unknown) => void,\n      finallyHandler?: () => void\n    ) =>\n    (...args: TArgs): TReturn | undefined => {\n      try {\n        return action(...args)\n      } catch (e) {\n        ;(errorHandler ?? toastErrorHandler)(e)\n      } finally {\n        finallyHandler?.()\n      }\n    }\n\n  const wrapWithErrorHandlingAsync =\n    <TArgs extends unknown[], TReturn>(\n      action: (...args: TArgs) => Promise<TReturn> | TReturn,\n      errorHandler?: (error: unknown) => void,\n      finallyHandler?: () => void,\n      recoveryStrategies: ErrorRecoveryStrategy<TArgs, TReturn>[] = []\n    ) =>\n    async (...args: TArgs): Promise<TReturn | undefined> => {\n      try {\n        return await action(...args)\n      } catch (e) {\n        for (const strategy of recoveryStrategies) {\n          if (strategy.shouldHandle(e)) {\n            try {\n              await strategy.recover(e, action, args)\n              return\n            } catch (recoveryError) {\n              console.error('Recovery strategy failed:', recoveryError)\n            }\n          }\n        }\n\n        ;(errorHandler ?? toastErrorHandler)(e)\n      } finally {\n        finallyHandler?.()\n      }\n    }\n\n  return {\n    wrapWithErrorHandling,\n    wrapWithErrorHandlingAsync,\n    toastErrorHandler\n  }\n}\n","/**\n * Tells the canvas which interactions the host application allows right now.\n * The application implements it over its own state and hands it to\n * {@link LGraphCanvas} through `options.interactionMode`; litegraph never\n * reads application stores.\n */\nexport interface CanvasInteractionModeReader {\n  /**\n   * `true` while the canvas is a picking surface: nodes can be selected and\n   * the view can be panned and zoomed, but nothing may change the graph.\n   */\n  isSelectOnly(): boolean\n}\n\nexport const EDITABLE_INTERACTION_MODE: CanvasInteractionModeReader = {\n  isSelectOnly: () => false\n}\n","export const RESERVED_BY_BROWSER = new Set([\n  'Ctrl + t', // New tab (all browsers)\n  'Ctrl + w', // Close tab (all browsers)\n  'Ctrl + n', // New window (all browsers)\n  'Ctrl + Shift + n', // New incognito/private window (all browsers)\n  'Ctrl + Tab', // Next tab (all browsers)\n  'Ctrl + Shift + Tab', // Previous tab (all browsers)\n  'Ctrl + Shift + Delete', // Clear browsing data (Chrome, Edge, Firefox)\n  'Ctrl + h', // History (all browsers)\n  'Ctrl + j', // Downloads (Chrome, Edge)\n  'Ctrl + d', // Bookmark current page (all browsers)\n  'Ctrl + Shift + b', // Toggle bookmarks bar (Chrome, Edge)\n  'Ctrl + Shift + o', // Bookmarks manager (Chrome, Edge)\n  'Ctrl + Shift + i', // DevTools (all browsers)\n  'Ctrl + Shift + j', // DevTools console (Chrome, Edge)\n  'F5', // Reload page (all browsers)\n  'Ctrl + F5', // Hard reload (all browsers)\n  'Ctrl + r', // Reload page (all browsers)\n  'Ctrl + Shift + r', // Hard reload (all browsers)\n  'F7', // Caret browsing (Firefox, Edge)\n  'F11', // Toggle fullscreen (all browsers)\n  'F12', // DevTools (all browsers)\n  'Alt + F4' // Close window (Windows, all browsers)\n])\n\nexport const RESERVED_BY_TEXT_INPUT = new Set([\n  'Ctrl + a',\n  'Ctrl + c',\n  'Ctrl + v',\n  'Ctrl + x',\n  'Ctrl + z',\n  'Ctrl + y',\n  'Ctrl + p',\n  'Enter',\n  'Shift + Enter',\n  'Ctrl + Backspace',\n  'Ctrl + Delete',\n  'Home',\n  'Ctrl + Home',\n  'Ctrl + Shift + Home',\n  'End',\n  'Ctrl + End',\n  'Ctrl + Shift + End',\n  'PageUp',\n  'PageDown',\n  'Shift + PageUp',\n  'Shift + PageDown',\n  'ArrowLeft',\n  'Ctrl + ArrowLeft',\n  'Shift + ArrowLeft',\n  'Ctrl + Shift + ArrowLeft',\n  'ArrowRight',\n  'Ctrl + ArrowRight',\n  'Shift + ArrowRight',\n  'Ctrl + Shift + ArrowRight',\n  'ArrowUp',\n  'Shift + ArrowUp',\n  'ArrowDown',\n  'Shift + ArrowDown'\n])\n","import { toRaw } from 'vue'\n\nimport { RESERVED_BY_BROWSER, RESERVED_BY_TEXT_INPUT } from './reserved'\nimport type { KeyCombo } from './types'\n\nconst MODIFIER_KEY_LABELS: Record<string, string> = {\n  Control: 'Ctrl',\n  Meta: 'Ctrl',\n  Alt: 'Alt',\n  Shift: 'Shift'\n}\n\nexport class KeyComboImpl implements KeyCombo {\n  key: string\n  ctrl: boolean\n  alt: boolean\n  shift: boolean\n\n  constructor(obj: KeyCombo) {\n    this.key = obj.key\n    this.ctrl = obj.ctrl ?? false\n    this.alt = obj.alt ?? false\n    this.shift = obj.shift ?? false\n  }\n\n  static fromEvent(event: KeyboardEvent) {\n    return new KeyComboImpl({\n      key: event.key,\n      ctrl: event.ctrlKey || event.metaKey,\n      alt: event.altKey,\n      shift: event.shiftKey\n    })\n  }\n\n  equals(other: unknown): boolean {\n    const raw = toRaw(other)\n\n    return raw instanceof KeyComboImpl\n      ? this.key.toUpperCase() === raw.key.toUpperCase() &&\n          this.ctrl === raw.ctrl &&\n          this.alt === raw.alt &&\n          this.shift === raw.shift\n      : false\n  }\n\n  serialize(): string {\n    return `${this.key.toUpperCase()}:${this.ctrl}:${this.alt}:${this.shift}`\n  }\n\n  toString(): string {\n    return this.getKeySequences().join(' + ')\n  }\n\n  get hasModifier(): boolean {\n    return this.ctrl || this.alt || this.shift\n  }\n\n  get isModifier(): boolean {\n    return this.key in MODIFIER_KEY_LABELS\n  }\n\n  get modifierCount(): number {\n    const modifiers = [this.ctrl, this.alt, this.shift]\n    return modifiers.reduce((acc, cur) => acc + Number(cur), 0)\n  }\n\n  get isShiftOnly(): boolean {\n    return this.shift && this.modifierCount === 1\n  }\n\n  get isBrowserReserved(): boolean {\n    return RESERVED_BY_BROWSER.has(toNormalizedString(this))\n  }\n\n  get isReservedByTextInput(): boolean {\n    return (\n      !this.hasModifier ||\n      this.isShiftOnly ||\n      RESERVED_BY_TEXT_INPUT.has(toNormalizedString(this))\n    )\n  }\n\n  getKeySequences(): string[] {\n    const sequences = getModifierSequences(this)\n\n    if (!this.isModifier || sequences.length === 0) {\n      sequences.push(getKeyLabel(this.key))\n    }\n\n    return sequences\n  }\n}\n\nfunction toNormalizedString(combo: KeyComboImpl): string {\n  const sequences = getModifierSequences(combo)\n\n  if (!combo.isModifier || sequences.length === 0) {\n    sequences.push(getKeyLabel(combo.key, true))\n  }\n\n  return sequences.join(' + ')\n}\n\nfunction getModifierSequences(combo: KeyComboImpl): string[] {\n  const sequences: string[] = []\n  if (combo.ctrl) sequences.push('Ctrl')\n  if (combo.alt) sequences.push('Alt')\n  if (combo.shift) sequences.push('Shift')\n  return sequences\n}\n\nfunction getKeyLabel(key: string, normalizeSingleCharacter = false): string {\n  const label = MODIFIER_KEY_LABELS[key] ?? key\n  return normalizeSingleCharacter && label.length === 1\n    ? label.toLowerCase()\n    : label\n}\n","import { toRaw } from 'vue'\n\nimport { KeyComboImpl } from './keyCombo'\nimport type { Keybinding } from './types'\n\nexport class KeybindingImpl implements Keybinding {\n  commandId: string\n  combo: KeyComboImpl\n  targetElementId?: string\n\n  constructor(obj: Keybinding) {\n    this.commandId = obj.commandId\n    this.combo = new KeyComboImpl(obj.combo)\n    this.targetElementId = obj.targetElementId\n  }\n\n  equals(other: unknown): boolean {\n    const raw = toRaw(other)\n\n    return raw instanceof KeybindingImpl\n      ? this.commandId === raw.commandId &&\n          this.combo.equals(raw.combo) &&\n          this.targetElementId === raw.targetElementId\n      : false\n  }\n}\n","import { groupBy } from 'es-toolkit/compat'\nimport { defineStore } from 'pinia'\nimport type { Ref } from 'vue'\nimport { computed, ref, shallowRef } from 'vue'\n\nimport type { KeyComboImpl } from './keyCombo'\nimport { KeybindingImpl } from './keybinding'\nimport type { KeybindingPreset } from './types'\n\ntype KeybindingMap = Partial<Record<string, KeybindingImpl>>\n\nfunction keybindingValues(keybindings: KeybindingMap): KeybindingImpl[] {\n  return Object.values(keybindings).filter(\n    (keybinding): keybinding is KeybindingImpl => keybinding !== undefined\n  )\n}\n\nexport const useKeybindingStore = defineStore('keybinding', () => {\n  const defaultKeybindings = shallowRef<KeybindingMap>({})\n  const userKeybindings = shallowRef<KeybindingMap>({})\n  const userUnsetKeybindings = shallowRef<KeybindingMap>({})\n\n  const currentPresetName = ref('default')\n  const savedPresetData = ref<KeybindingPreset | null>(null)\n\n  const serializeBinding = (b: KeybindingImpl) =>\n    `${b.commandId}:${b.combo.serialize()}:${b.targetElementId ?? ''}`\n\n  const savedPresetSerialized = computed(() => {\n    if (!savedPresetData.value) return null\n    const savedNew = savedPresetData.value.newBindings\n      .map((b) => serializeBinding(new KeybindingImpl(b)))\n      .sort()\n      .join('|')\n    const savedUnset = savedPresetData.value.unsetBindings\n      .map((b) => serializeBinding(new KeybindingImpl(b)))\n      .sort()\n      .join('|')\n    return { savedNew, savedUnset }\n  })\n\n  const isCurrentPresetModified = computed(() => {\n    const newBindings = keybindingValues(userKeybindings.value)\n    const unsetBindings = keybindingValues(userUnsetKeybindings.value)\n\n    if (currentPresetName.value === 'default') {\n      return newBindings.length > 0 || unsetBindings.length > 0\n    }\n\n    if (!savedPresetSerialized.value) return false\n\n    const currentNew = newBindings.map(serializeBinding).sort().join('|')\n    const currentUnset = unsetBindings.map(serializeBinding).sort().join('|')\n\n    return (\n      currentNew !== savedPresetSerialized.value.savedNew ||\n      currentUnset !== savedPresetSerialized.value.savedUnset\n    )\n  })\n\n  function getUserKeybindings() {\n    return userKeybindings.value\n  }\n\n  function getUserKeybindingValues() {\n    return keybindingValues(userKeybindings.value)\n  }\n\n  function getUserUnsetKeybindings() {\n    return userUnsetKeybindings.value\n  }\n\n  function getUserUnsetKeybindingValues() {\n    return keybindingValues(userUnsetKeybindings.value)\n  }\n\n  const keybindingByKeyCombo = computed<KeybindingMap>(() => {\n    const result: KeybindingMap = {\n      ...defaultKeybindings.value\n    }\n\n    for (const keybinding of keybindingValues(userUnsetKeybindings.value)) {\n      const serializedCombo = keybinding.combo.serialize()\n      if (result[serializedCombo]?.equals(keybinding)) {\n        delete result[serializedCombo]\n      }\n    }\n\n    return {\n      ...result,\n      ...userKeybindings.value\n    }\n  })\n\n  const keybindings = computed<KeybindingImpl[]>(() =>\n    keybindingValues(keybindingByKeyCombo.value)\n  )\n\n  function getKeybinding(combo: KeyComboImpl): KeybindingImpl | undefined {\n    return keybindingByKeyCombo.value[combo.serialize()]\n  }\n\n  const keybindingsByCommandId = computed<\n    Partial<Record<string, KeybindingImpl[]>>\n  >(() => {\n    return groupBy(keybindings.value, 'commandId')\n  })\n\n  function getKeybindingsByCommandId(commandId: string) {\n    return keybindingsByCommandId.value[commandId] ?? []\n  }\n\n  const defaultKeybindingsByCommandId = computed<\n    Partial<Record<string, KeybindingImpl[]>>\n  >(() => groupBy(keybindingValues(defaultKeybindings.value), 'commandId'))\n\n  function getKeybindingByCommandId(commandId: string) {\n    return getKeybindingsByCommandId(commandId).at(0)\n  }\n\n  function addKeybinding(\n    target: Ref<KeybindingMap>,\n    keybinding: KeybindingImpl,\n    { existOk }: { existOk: boolean }\n  ) {\n    const existing = target.value[keybinding.combo.serialize()]\n    if (!existOk && existing) {\n      throw new Error(\n        `Keybinding on ${keybinding.combo} already exists on ${existing.commandId}`\n      )\n    }\n    target.value = {\n      ...target.value,\n      [keybinding.combo.serialize()]: keybinding\n    }\n  }\n\n  function addDefaultKeybinding(keybinding: KeybindingImpl) {\n    addKeybinding(defaultKeybindings, keybinding, { existOk: false })\n  }\n\n  function addUserKeybinding(keybinding: KeybindingImpl) {\n    const serializedCombo = keybinding.combo.serialize()\n    const defaultKeybinding = defaultKeybindings.value[serializedCombo]\n    const userUnsetKeybinding = userUnsetKeybindings.value[serializedCombo]\n\n    if (\n      keybinding.equals(defaultKeybinding) &&\n      keybinding.equals(userUnsetKeybinding)\n    ) {\n      const updated = { ...userUnsetKeybindings.value }\n      delete updated[keybinding.combo.serialize()]\n      userUnsetKeybindings.value = updated\n      return\n    }\n\n    if (defaultKeybinding && !defaultKeybinding.equals(userUnsetKeybinding)) {\n      unsetKeybinding(defaultKeybinding)\n    }\n\n    addKeybinding(userKeybindings, keybinding, { existOk: true })\n  }\n\n  function unsetKeybinding(keybinding: KeybindingImpl) {\n    const serializedCombo = keybinding.combo.serialize()\n    if (!(serializedCombo in keybindingByKeyCombo.value)) {\n      console.warn(\n        `Trying to unset non-exist keybinding: ${JSON.stringify(keybinding)}`\n      )\n      return\n    }\n\n    if (userKeybindings.value[serializedCombo]?.equals(keybinding)) {\n      const updated = { ...userKeybindings.value }\n      delete updated[serializedCombo]\n      userKeybindings.value = updated\n      return\n    }\n\n    if (defaultKeybindings.value[serializedCombo]?.equals(keybinding)) {\n      addKeybinding(userUnsetKeybindings, keybinding, { existOk: false })\n      return\n    }\n\n    console.warn(`Unset unknown keybinding: ${JSON.stringify(keybinding)}`)\n  }\n\n  function updateKeybindingOnCommand(keybinding: KeybindingImpl): boolean {\n    const currentKeybinding = getKeybindingByCommandId(keybinding.commandId)\n    if (currentKeybinding?.equals(keybinding)) {\n      return false\n    }\n    if (currentKeybinding) {\n      unsetKeybinding(currentKeybinding)\n    }\n    addUserKeybinding(keybinding)\n    return true\n  }\n\n  function resetAllKeybindings() {\n    userKeybindings.value = {}\n    userUnsetKeybindings.value = {}\n  }\n\n  function removeAllKeybindingsForCommand(commandId: string): boolean {\n    const currentBindings = getKeybindingsByCommandId(commandId)\n    if (currentBindings.length === 0) return false\n    for (const binding of currentBindings) {\n      unsetKeybinding(binding)\n    }\n    return true\n  }\n\n  function updateSpecificKeybinding(\n    oldBinding: KeybindingImpl,\n    newBinding: KeybindingImpl\n  ) {\n    unsetKeybinding(oldBinding)\n    addUserKeybinding(newBinding)\n  }\n\n  function resetKeybindingForCommand(commandId: string): boolean {\n    const currentBindings = getKeybindingsByCommandId(commandId)\n    const defaultBindings = defaultKeybindingsByCommandId.value[commandId] ?? []\n\n    if (defaultBindings.length === 0) {\n      if (currentBindings.length > 0) {\n        for (const binding of currentBindings) {\n          unsetKeybinding(binding)\n        }\n        return true\n      }\n      return false\n    }\n\n    if (!isCommandKeybindingModified(commandId)) {\n      return false\n    }\n\n    for (const binding of currentBindings) {\n      unsetKeybinding(binding)\n    }\n\n    const updatedUnset = { ...userUnsetKeybindings.value }\n    for (const defaultBinding of defaultBindings) {\n      const serializedCombo = defaultBinding.combo.serialize()\n      if (updatedUnset[serializedCombo]?.equals(defaultBinding)) {\n        delete updatedUnset[serializedCombo]\n      }\n    }\n    userUnsetKeybindings.value = updatedUnset\n\n    return true\n  }\n\n  const modifiedCommandIds = computed<Set<string>>(() => {\n    const result = new Set<string>()\n    const allCommandIds = new Set([\n      ...Object.keys(keybindingsByCommandId.value),\n      ...Object.keys(defaultKeybindingsByCommandId.value)\n    ])\n\n    for (const commandId of allCommandIds) {\n      const currentBindings = keybindingsByCommandId.value[commandId] ?? []\n      const defaultBindings =\n        defaultKeybindingsByCommandId.value[commandId] ?? []\n\n      if (currentBindings.length !== defaultBindings.length) {\n        result.add(commandId)\n        continue\n      }\n      if (currentBindings.length === 0) continue\n\n      const sortedCurrent = [...currentBindings]\n        .map((b) => b.combo.serialize())\n        .sort()\n      const sortedDefault = [...defaultBindings]\n        .map((b) => b.combo.serialize())\n        .sort()\n\n      if (sortedCurrent.some((combo, i) => combo !== sortedDefault[i])) {\n        result.add(commandId)\n      }\n    }\n\n    return result\n  })\n\n  function isCommandKeybindingModified(commandId: string): boolean {\n    return modifiedCommandIds.value.has(commandId)\n  }\n\n  return {\n    keybindings,\n    getUserKeybindings,\n    getUserKeybindingValues,\n    getUserUnsetKeybindings,\n    getUserUnsetKeybindingValues,\n    getKeybinding,\n    getKeybindingsByCommandId,\n    getKeybindingByCommandId,\n    addDefaultKeybinding,\n    addUserKeybinding,\n    unsetKeybinding,\n    updateKeybindingOnCommand,\n    resetAllKeybindings,\n    resetKeybindingForCommand,\n    isCommandKeybindingModified,\n    currentPresetName,\n    savedPresetData,\n    isCurrentPresetModified,\n    removeAllKeybindingsForCommand,\n    updateSpecificKeybinding\n  }\n})\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport type { CanvasInteractionModeReader } from '@/lib/litegraph/src/canvas/CanvasInteractionMode'\nimport { EDITABLE_INTERACTION_MODE } from '@/lib/litegraph/src/canvas/CanvasInteractionMode'\nimport type { KeybindingImpl } from '@/platform/keybindings/keybinding'\nimport { useKeybindingStore } from '@/platform/keybindings/keybindingStore'\n\nexport interface ComfyCommand {\n  id: string\n  function: (metadata?: Record<string, unknown>) => void | Promise<void>\n\n  label?: string | (() => string)\n  icon?: string | (() => string)\n  tooltip?: string | (() => string)\n  menubarLabel?: string | (() => string) // Menubar item label, if different from command label\n  versionAdded?: string\n  confirmation?: string // If non-nullish, this command will prompt for confirmation\n  source?: string\n  active?: () => boolean // Getter to check if the command is active/toggled on\n  category?: 'essentials' | 'view-controls' // For shortcuts panel organization\n  /** Refused by `execute()` while the canvas interaction mode is select-only. */\n  mutatesGraph?: boolean | (() => boolean)\n}\n\nfunction mutatesGraph(command: ComfyCommand): boolean {\n  return typeof command.mutatesGraph === 'function'\n    ? command.mutatesGraph()\n    : command.mutatesGraph === true\n}\n\nexport class ComfyCommandImpl implements ComfyCommand {\n  id: string\n  function: (metadata?: Record<string, unknown>) => void | Promise<void>\n  _label?: string | (() => string)\n  _icon?: string | (() => string)\n  _tooltip?: string | (() => string)\n  _menubarLabel?: string | (() => string)\n  versionAdded?: string\n  confirmation?: string\n  source?: string\n  active?: () => boolean\n  category?: 'essentials' | 'view-controls'\n  mutatesGraph?: boolean | (() => boolean)\n\n  constructor(command: ComfyCommand) {\n    this.id = command.id\n    this.function = command.function\n    this._label = command.label\n    this._icon = command.icon\n    this._tooltip = command.tooltip\n    this._menubarLabel = command.menubarLabel ?? command.label\n    this.versionAdded = command.versionAdded\n    this.confirmation = command.confirmation\n    this.source = command.source\n    this.active = command.active\n    this.category = command.category\n    this.mutatesGraph = command.mutatesGraph\n  }\n\n  get label() {\n    return typeof this._label === 'function' ? this._label() : this._label\n  }\n\n  get icon() {\n    return typeof this._icon === 'function' ? this._icon() : this._icon\n  }\n\n  get tooltip() {\n    return typeof this._tooltip === 'function' ? this._tooltip() : this._tooltip\n  }\n\n  get menubarLabel() {\n    return typeof this._menubarLabel === 'function'\n      ? this._menubarLabel()\n      : this._menubarLabel\n  }\n\n  get keybinding(): KeybindingImpl | null {\n    return useKeybindingStore().getKeybindingByCommandId(this.id) ?? null\n  }\n}\n\nexport const useCommandStore = defineStore('command', () => {\n  const commandsById = ref<Record<string, ComfyCommandImpl>>({})\n  const commands = computed(() => Object.values(commandsById.value))\n\n  const registerCommand = (command: ComfyCommand) => {\n    if (command.id in commandsById.value) {\n      console.warn(`Command ${command.id} already registered`)\n    }\n    commandsById.value[command.id] = new ComfyCommandImpl(command)\n  }\n\n  const registerCommands = (commands: ComfyCommand[]) => {\n    for (const command of commands) {\n      registerCommand(command)\n    }\n  }\n\n  const getCommand = (command: string) => {\n    return commandsById.value[command]\n  }\n\n  let interactionMode: CanvasInteractionModeReader = EDITABLE_INTERACTION_MODE\n  const setInteractionMode = (mode: CanvasInteractionModeReader) => {\n    interactionMode = mode\n  }\n\n  const { wrapWithErrorHandlingAsync } = useErrorHandling()\n  const execute = async (\n    commandId: string,\n    options?: {\n      errorHandler?: (error: unknown) => void\n      metadata?: Record<string, unknown>\n    }\n  ) => {\n    if (!(commandId in commandsById.value)) {\n      throw new Error(`Command ${commandId} not found`)\n    }\n    const command = getCommand(commandId)\n    if (interactionMode.isSelectOnly() && mutatesGraph(command)) return\n    await wrapWithErrorHandlingAsync(\n      () => command.function(options?.metadata),\n      options?.errorHandler\n    )()\n  }\n\n  const isRegistered = (command: string) => {\n    return !!commandsById.value[command]\n  }\n\n  const loadExtensionCommands = (extension: {\n    name: string\n    commands?: ComfyCommand[]\n  }) => {\n    if (extension.commands) {\n      for (const command of extension.commands) {\n        registerCommand({\n          ...command,\n          source: extension.name\n        })\n      }\n    }\n  }\n\n  const formatKeySequence = (command: ComfyCommandImpl): string => {\n    const sequences = command.keybinding?.combo.getKeySequences() || []\n    return sequences\n      .map((seq) => seq.replace(/Control/g, 'Ctrl').replace(/Shift/g, 'Shift'))\n      .join(' + ')\n  }\n\n  return {\n    commands,\n    execute,\n    getCommand,\n    registerCommand,\n    registerCommands,\n    isRegistered,\n    setInteractionMode,\n    loadExtensionCommands,\n    formatKeySequence\n  }\n})\n"],"mappings":"4PAmDA,SAAgB,kBAAmB,CACjC,IAAM,EAAQ,EAAS,EACjB,kBAAqB,GAAmB,CAI5C,IAAM,EAFJ,aAAiB,WACjB,4CAA4C,KAAK,EAAM,OAAO,EAE5D,EAAE,2BAA2B,EAC7B,aAAiB,MACf,EAAM,QACN,EAAE,gBAAgB,EACxB,EAAM,MAAM,EAAE,SAAS,EAAG,CAAE,YAAa,CAAQ,CAAC,EAClD,QAAQ,MAAM,CAAK,CACrB,EAEM,uBAEF,EACA,EACA,KAED,GAAG,IAAqC,CACvC,GAAI,CACF,OAAO,EAAO,GAAG,CAAI,CACvB,OAAS,EAAG,EACR,GAAgB,kBAAA,CAAmB,CAAC,CACxC,QAAU,CACR,IAAiB,CACnB,CACF,EAEI,4BAEF,EACA,EACA,EACA,EAA8D,CAAC,IAEjE,MAAO,GAAG,IAA8C,CACtD,GAAI,CACF,OAAO,MAAM,EAAO,GAAG,CAAI,CAC7B,OAAS,EAAG,CACV,IAAK,IAAM,KAAY,EACrB,GAAI,EAAS,aAAa,CAAC,EACzB,GAAI,CACF,MAAM,EAAS,QAAQ,EAAG,EAAQ,CAAI,EACtC,MACF,OAAS,EAAe,CACtB,QAAQ,MAAM,4BAA6B,CAAa,CAC1D,EAIF,GAAgB,kBAAA,CAAmB,CAAC,CACxC,QAAU,CACR,IAAiB,CACnB,